    private static final int PROCESSING_FEE = 5;
    private static final double FIRST_INSURANCE_SURCHARGE = 0.10;
    private static final int COMPONENT_BLOCK_SIZE = 3;
    private static final int COMPONENT_BLOCK_PREMIUM = 60;

    private static final Map<String, Integer> BASE_PREMIUMS = Map.of(
            "sword", 100,
            "amulet", 60,
            "staff", 80,
            "potion", 40,
            "rune", 25,
            "moonstone", 25);

    private static final List<String> COMPONENT_TYPES = List.of("rune", "moonstone");

    private final int yearsWithMhpco;

    public ClaimOffice(int yearsWithMhpco) {
        this.yearsWithMhpco = yearsWithMhpco;
    }

    public int quote(List<Map<String, Object>> items) {
        double base = policyBasePremium(items);
        double premium = base + base * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
        return (int) Math.ceil(premium);
    }

    private double policyBasePremium(List<Map<String, Object>> items) {
        double base = 0;
        Map<String, List<Map<String, Object>>> components = new LinkedHashMap<>();
        for (Map<String, Object> item : items) {
            String type = (String) item.get("type");
            if (COMPONENT_TYPES.contains(type)) {
                components.computeIfAbsent(type, unused -> new ArrayList<>()).add(item);
            } else {
                base += basePremiumOf(item);
            }
        }
        for (List<Map<String, Object>> alike : components.values()) {
            base += componentGroupBasePremium(alike);
        }
        return base;
    }

    private double componentGroupBasePremium(List<Map<String, Object>> alike) {
        if (alike.size() == COMPONENT_BLOCK_SIZE) {
            return COMPONENT_BLOCK_PREMIUM;
        }
        double base = 0;
        for (Map<String, Object> component : alike) {
            base += basePremiumOf(component);
        }
        return base;
    }

    private double basePremiumOf(Map<String, Object> item) {
        return BASE_PREMIUMS.get(item.get("type"));
    }
}
